void prg_out_anti_grind( Boolean ctrl )
{
    prg_out_execute( 1 + PRG_OUT_AG_STARTER_KILL , ctrl ) ;     // combined AG and starterkill
	  
	  if( dei_out_gwr )
			ctrl = FALSE;		// pure starter kill is always OFF when gwr is true
    prg_out_execute( 1 + PRG_OUT_ANTI_GRIND , ctrl ) ;  // listed as "starterkill"
}

